void drm_gem_shmem_unpin(struct drm_gem_shmem_object *shmem) /* <=== drm_gem_shmem_unpin */ 
{
	WARN_ON(shmem->base.import_attach);

	drm_gem_shmem_put_pages(shmem);
}

int drm_gem_shmem_pin(struct drm_gem_shmem_object *shmem) /* <=== drm_gem_shmem_pin */ 
{
	WARN_ON(shmem->base.import_attach);

	return drm_gem_shmem_get_pages(shmem);
}

static inline unsigned long page_to_phys(struct page *page) /* <=== page_to_phys */ 
{
	assert(0);

	return 0;
}

static inline struct page *sg_page(struct scatterlist *sg) /* <=== sg_page */ 
{
#ifdef CONFIG_DEBUG_SG
	BUG_ON(sg_is_chain(sg));
#endif
	return (struct page *)((sg)->page_link & ~0x3);
}

void drm_gem_shmem_put_pages(struct drm_gem_shmem_object *shmem) /* <=== drm_gem_shmem_put_pages */ 
{
	mutex_lock(&shmem->pages_lock);
	drm_gem_shmem_put_pages_locked(shmem);
	mutex_unlock(&shmem->pages_lock);
}

struct sg_table *drm_gem_shmem_get_sg_table(struct drm_gem_shmem_object *shmem) /* <=== drm_gem_shmem_get_sg_table */ 
{
	struct drm_gem_object *obj = &shmem->base;

	WARN_ON(shmem->base.import_attach);

	return drm_prime_pages_to_sg(obj->dev, shmem->pages, obj->size >> PAGE_SHIFT);
}

static inline struct page *sg_page(struct scatterlist *sg) /* <=== sg_page */ 
{
#ifdef CONFIG_DEBUG_SG
	BUG_ON(sg_is_chain(sg));
#endif
	return (struct page *)((sg)->page_link & ~SG_PAGE_LINK_MASK);
}

static int drm_gem_shmem_get_pages_locked(struct drm_gem_shmem_object *shmem) /* <=== drm_gem_shmem_get_pages_locked */ 
{
	struct drm_gem_object *obj = &shmem->base;
	struct page **pages;

	if (shmem->pages_use_count++ > 0)
		return 0;

	pages = drm_gem_get_pages(obj);
	if (IS_ERR(pages)) {
		DRM_DEBUG_KMS("Failed to get pages (%ld)\n", PTR_ERR(pages));
		shmem->pages_use_count = 0;
		return PTR_ERR(pages);
	}

	/*
	 * TODO: Allocating WC pages which are correctly flushed is only
	 * supported on x86. Ideal solution would be a GFP_WC flag, which also
	 * ttm_pool.c could use.
	 */
#ifdef CONFIG_X86
	if (shmem->map_wc)
		set_pages_array_wc(pages, obj->size >> PAGE_SHIFT);
#endif

	shmem->pages = pages;

	return 0;
}

static inline dma_addr_t sg_phys(struct scatterlist *sg) /* <=== sg_phys */ 
{
	return page_to_phys(sg_page(sg)) + sg->offset;
}

int drm_gem_shmem_get_pages(struct drm_gem_shmem_object *shmem) /* <=== drm_gem_shmem_get_pages */ 
{
	int ret;

	WARN_ON(shmem->base.import_attach);

	ret = mutex_lock_interruptible(&shmem->pages_lock);
	if (ret)
		return ret;
	ret = drm_gem_shmem_get_pages_locked(shmem);
	mutex_unlock(&shmem->pages_lock);

	return ret;
}

static void drm_gem_shmem_put_pages_locked(struct drm_gem_shmem_object *shmem) /* <=== drm_gem_shmem_put_pages_locked */ 
{
	struct drm_gem_object *obj = &shmem->base;

	if (WARN_ON_ONCE(!shmem->pages_use_count))
		return;

	if (--shmem->pages_use_count > 0)
		return;

#ifdef CONFIG_X86
	if (shmem->map_wc)
		set_pages_array_wb(shmem->pages, obj->size >> PAGE_SHIFT);
#endif

	drm_gem_put_pages(obj, shmem->pages,
			  shmem->pages_mark_dirty_on_put,
			  shmem->pages_mark_accessed_on_put);
	shmem->pages = NULL;
}

static inline int dma_map_sgtable(struct device *dev, struct sg_table *sgt, /* <=== dma_map_sgtable */ 
		enum dma_data_direction dir, unsigned long attrs)
{
	return -EOPNOTSUPP;
}

